<template>
  <q-page class="page">
    <section class="top"><div><p class="eyebrow">BANCO PUBLICADO</p><h1 class="page-title">Questões</h1><p>Explore itens disponíveis para seus próximos cadernos.</p></div><q-btn flat no-caps color="primary" label="Limpar filtros" @click="clear" /></section>
    <q-card flat class="filters"><q-card-section class="filter-grid"><q-input v-model="filters.content" outlined dense clearable label="Pesquisar no conteúdo" placeholder="Enunciado ou alternativa" @keyup.enter="search"><template #prepend><q-icon name="search" /></template></q-input><q-input v-model="filters.board" outlined dense label="Banca" @keyup.enter="search" /><q-input v-model.number="filters.year" outlined dense type="number" label="Ano" @keyup.enter="search" /><q-select v-model="filters.difficulty" clearable outlined dense label="Dificuldade" :options="difficultyOptions" emit-value map-options /><q-btn unelevated no-caps color="primary" label="Filtrar" :loading="loading" @click="search" /></q-card-section></q-card>
    <q-banner v-if="error" rounded class="error">{{ error }}</q-banner>
    <p class="results">{{ total }} {{ total === 1 ? 'questão encontrada' : 'questões encontradas' }}</p>
    <q-inner-loading :showing="loading" color="primary" />
    <section v-if="questions.length" class="question-results"><q-card v-for="(question, index) in questions" :key="question.id" flat class="question-workspace"><q-card-section><div class="question-meta"><strong>Questão {{ (page - 1) * perPage + index + 1 }}</strong><q-badge rounded color="amber-2" text-color="amber-10">{{ difficulty(question.difficulty) }}</q-badge><q-chip v-if="question.board" dense color="blue-1" text-color="primary">{{ question.board }}{{ question.year ? " · " + question.year : "" }}</q-chip><q-badge v-if="question.answerKeySource === 'AI_ESTIMATED'" color="warning" text-color="dark" label="Gabarito estimado por IA"/></div><div v-if="question.assetUrls?.length" class="question-assets"><QuestionAssetImage v-for="url in question.assetUrls" :key="url" :url="url"/></div><div class="question-statement"><QuestionContent :value="question.statement"/></div><div class="question-options" role="list" aria-label="Alternativas"><div v-for="option in question.options" :key="option.id" class="option-card" role="listitem"><q-icon name="radio_button_unchecked"/><strong>{{ option.label }}.</strong><QuestionContent :value="option.content"/><div v-if="option.assetUrls?.length" class="option-assets"><QuestionAssetImage v-for="url in option.assetUrls" :key="url" :url="url"/></div></div></div></q-card-section></q-card></section>
    <div v-if="total > perPage" class="pagination"><q-pagination :model-value="page" :max="Math.ceil(total / perPage)" :max-pages="7" color="primary" boundary-numbers @update:model-value="goTo" /></div>
    <q-card v-if="!loading && !questions.length" flat class="empty"><q-card-section><q-img src="/images/concursos-study-mark.png" width="84px" height="84px" fit="contain" /><div><h2>Nenhuma questão para estes filtros</h2><p>Tente remover filtros ou peça a inclusão de questões publicadas.</p></div></q-card-section></q-card>
  </q-page>
</template>
<script setup lang="ts">
import { onMounted, reactive } from 'vue'
import QuestionAssetImage from './QuestionAssetImage.vue'
import QuestionContent from './QuestionContent.vue'
import type { QuestionDifficulty } from '../../../Domain/QuestionBank/QuestionRepository'
import { useQuestions } from './useQuestions'
const { error, goTo, load, loading, page, perPage, questions, total } = useQuestions()
const filters = reactive<{ content: string; board: string; year: number | null; difficulty: QuestionDifficulty | null }>({ content: '', board: '', year: null, difficulty: null })
const difficultyOptions = [{ label: 'Fácil', value: 'EASY' }, { label: 'Média', value: 'MEDIUM' }, { label: 'Difícil', value: 'HARD' }]
function search(): Promise<void> { return load({ ...(filters.content.trim() ? { content: filters.content.trim() } : {}), ...(filters.board.trim() ? { board: filters.board.trim() } : {}), ...(filters.year ? { year: filters.year } : {}), ...(filters.difficulty ? { difficulty: filters.difficulty } : {}) }) }
function clear(): void { filters.content = ''; filters.board = ''; filters.year = null; filters.difficulty = null; void search() }
function difficulty(value: QuestionDifficulty): string { return ({ EASY: 'Fácil', MEDIUM: 'Média', HARD: 'Difícil' })[value] }
onMounted(search)
</script>
<style scoped>
