ts :deep(img){max-width:100%;max-height:430px;object-fit:contain;border:1px solid #dce6f4;border-radius:10px}.option{display:flex;align-items:flex-start;gap:9px;padding:10px 13px;margin:8px 0;border-radius:10px;background:#f7f9fd;color:#405174}.option :deep(.content){flex:1}.option-assets{width:100%}.empty :deep(.q-card__section){display:flex;align-items:center;gap:22px;padding:32px}.empty h2{margin:0;color:#1a315a;font-size:19px}.empty p{color:#71819e}.pagination{display:flex;justify-content:center;margin:22px 0}.error{margin-top:15px;background:#fff3f2;color:#ae2f25}@media(max-width:660px){.page{padding:28px 16px}.top{align-items:flex-start;flex-direction:column}.filter-grid{grid-template-columns:1fr}.filters .q-btn{height:42px}.empty :deep(.q-card__section){align-items:flex-start;flex-direction:column}}

/* Banco: leitura de questões em página fluida, com filtros em uma faixa discreta. */
.page{max-width:1240px!important}.top{padding:9px 0 23px;border-bottom:1px solid #dce7f6}.filters{border-radius:18px!important;background:rgba(255,255,255,.72)!important}.question-card{border-radius:22px!important;background:rgba(255,255,255,.84)!important}.question-card:hover{transform:translateY(-2px);box-shadow:0 15px 34px rgba(37,71,126,.10)!important}.empty{border-radius:24px!important;background:linear-gradient(145deg,#fff,#eef6ff)!important}
</style>
